# components by same-color 4-neighbor
R=C=10; seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  col=grid[r][c]
  if col in (0,2) or (r,c) in seen: continue
  st=[(r,c)]; seen.add((r,c)); cells=[]
  while st:
   x,y=st.pop(); cells.append((x,y))
   for nx,ny in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
    if 0<=nx<R and 0<=ny<C and grid[nx][ny]==col and (nx,ny) not in seen: seen.add((nx,ny));st.append((nx,ny))
  comps.append((col,cells))
comps.sort(key=lambda q:min(x for x,y in q[1]))
board=[[0]*C for _ in range(R)]; board[0]=[2]*C
for col,cells in comps:
 # all objects initial locations ignored, fall up against already placed
 cells=set(cells)
 while min(x for x,y in cells)>1 and all(board[x-1][y]==0 for x,y in cells):
  cells={(x-1,y) for x,y in cells}
 for x,y in cells: board[x][y]=col
print(comps); print(*board,sep='\n')
